{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative (sentiment < 0) or shows early negative momentum.",
    "Increase forecast sensitivity to recent price spikes — if true outcome exceeds forecast by >10%, apply a 15-20% upward correction in next period.",
    "Apply mean reversion bias: if forecast is consistently 5-10% above true outcome over 5+ days, reduce forecast by 2-3% per day.",
    "Lag correction: if true outcome is higher than forecast, delay adjustment by 1-2 days to avoid overreacting to short-term noise.",
    "For sentiment = 0.67 or higher, increase forecast by 3-5% to capture bullish momentum; for sentiment < 0.33, reduce by 3-5% to hedge downside risk."
  ]
}
